    "command": "env 'NO_COLOR=1' 'LEAN_BRIDGE_NATIVE_TEST_GLIBC_FLOOR=2.36' 'LEAN_BRIDGE_LEAN_PREFIX=/app/.toolchains/elan/toolchains/leanprover--lean4---v4.32.2' 'LEAN_NUM_THREADS=1' 'OMP_NUM_THREADS=1' 'MAKEFLAGS=-j1' 'LEAN_BRIDGE_GENERIC_RECORD_ARRAY_PROFILES=wit-wasi' 'LEAN_BRIDGE_GENERIC_RECORD_ARRAY_REPORT=/app/build/vo1439-generic-record-arrays-hosts-c92090f/array-wit-wasi.json' 'LEAN_BRIDGE_WASMTIME_C_API=/app/.toolchains/wasmtime42' 'LEAN_BRIDGE_WASM_TOOLS=/app/.toolchains/wasm-tools/bin/wasm-tools' '/usr/bin/taskset' '-c' '3' '/usr/bin/node' '--test' '--test-concurrency=1' '--test-reporter=tap' '--test-name-pattern=^relocated source-free native packages carry Array fields and results over alias-named generic records$' 'tests/generic-record-arrays.test.mjs'",
